import sys

def main():
    input = sys.stdin.read().split()
    idx = 0

    h = int(input[idx]); idx += 1
    w = int(input[idx]); idx += 1
    q = int(input[idx]); idx += 1

    grid = []
    for _ in range(h):
        grid.append(input[idx]); idx += 1

    start_r, start_c = 0, 0
    end_r, end_c = h - 1, w - 1

    def get_neighbors(r, c, blocked_set):
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < h and 0 <= nc < w:
                if (nr, nc) not in blocked_set:
                    if grid[nr][nc] == '.':
                        yield (nr, nc)

    def dfs_path(start, end, blocked_set, visited):
        stack = [(start[0], start[1], [start])]
        visited.add(start)

        while stack:
            r, c, path = stack.pop()
            if (r, c) == end:
                return path
            for nr, nc in get_neighbors(r, c, blocked_set):
                if (nr, nc) not in visited:
                    visited.add((nr, nc))
                    new_path = path + [(nr, nc)]
                    stack.append((nr, nc, new_path))
        return None

    results = []

    for _ in range(q):
        k = int(input[idx]); idx += 1
        blocked_set = set()
        for _ in range(k):
            r = int(input[idx]) - 1; idx += 1
            c = int(input[idx]) - 1; idx += 1
            blocked_set.add((r, c))

        visited_go = set()
        path_go = dfs_path((start_r, start_c), (end_r, end_c), blocked_set, visited_go)

        if path_go is None:
            results.append("NO")
            continue

        visited_return = set(path_go)
        path_return = dfs_path((end_r, end_c), (start_r, start_c), blocked_set, visited_return)

        if path_return is None:
            results.append("NO")
        else:
            results.append("YES")

    for res in results:
        print(res)
        sys.stdout.flush()

if __name__ == "__main__":
    main()
